import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/configuration.md","filePath":"en/modules/station/configuration.md","lastUpdated":0}`),a={name:`en/modules/station/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p><code>plugins/EmakiStation/config.yml</code> is the main configuration. Its <code>version</code> is a configuration-structure marker that the plugin uses to merge newly added default keys. It tracks separately from the module release version, so you do not need to edit it to match the plugin version.</p><h2 id="top-level-keys" tabindex="-1">Top-Level Keys <a class="header-anchor" href="#top-level-keys" aria-label="Permalink to “Top-Level Keys”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td><code>&quot;1.0.8&quot;</code></td><td>Configuration-structure marker, maintained by default-resource sync. The internal migration constant is <code>1.0.2</code> and is not a release coordinate.</td></tr><tr><td><code>language</code></td><td><code>&quot;zh_CN&quot;</code></td><td>Language file name, resolving to <code>lang/&lt;language&gt;.yml</code>.</td></tr><tr><td><code>release_default_data</code></td><td><code>true</code></td><td>Whether to release example data on first start (the example files under <code>stations/</code>, <code>gui/</code> and <code>recipes/</code>). Once false, existing files are not overwritten and missing examples are not restored.</td></tr></tbody></table><h2 id="queue-—-queue-defaults" tabindex="-1"><code>queue</code> — Queue Defaults <a class="header-anchor" href="#queue-—-queue-defaults" aria-label="Permalink to “queue — Queue Defaults”">​</a></h2><p>Every station may override these same keys in its own <code>stations/&lt;id&gt;.yml</code>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>base_length</code></td><td><code>3</code></td><td>Base queue length. Only <code>waiting</code> / <code>running</code> occupy length; <code>pending_claim</code> does not.</td></tr><tr><td><code>permission_tiers</code></td><td><code>true</code></td><td>Whether permission tiers apply. When enabled, the highest number among <code>emakistation.queue.&lt;n&gt;</code> wins.</td></tr><tr><td><code>max_length</code></td><td><code>32</code></td><td>Hard ceiling after tiers; no permission can exceed it.</td></tr><tr><td><code>progress_mode</code></td><td><code>&quot;offline&quot;</code></td><td>How the head advances: <code>offline</code> follows real time, <code>online</code> only accumulates while the player is online.</td></tr><tr><td><code>cancel_refund_rate</code></td><td><code>1.0</code></td><td>Fraction of materials refunded when cancelling an entry (0.0 – 1.0).</td></tr><tr><td><code>tick_interval</code></td><td><code>20</code></td><td>Interval of the queue advance task, in ticks. There is exactly one server-wide timer.</td></tr><tr><td><code>speed_multiplier</code></td><td><code>1.0</code></td><td>Global recipe duration multiplier. Values of 0 or below are treated as 1.0.</td></tr><tr><td><code>purchase.enabled</code></td><td><code>true</code></td><td>Server-wide master switch for paid queue slots.</td></tr><tr><td><code>purchase.cost_file</code></td><td><code>&quot;queue_costs.yml&quot;</code></td><td>Price tier file name, relative to the plugin data folder.</td></tr></tbody></table><p><code>pending_claim</code> not occupying queue length is deliberate: otherwise a player whose warehouse and inventory are both full would be deadlocked by their own undelivered output.</p><p><code>cancel_refund_rate</code> is not prorated by progress. In a serial single-line queue only the head has progress, and introducing per-entry progress accounting for an almost non-existent case is not worth it. This is an intentional simplification.</p><p><code>progress_mode: offline</code> only means &quot;the timer keeps running&quot;, not &quot;delivery while offline&quot;. EmakiStorage refuses any write for an offline player, so entries that come due while offline are merely &quot;due&quot;; settlement happens at the player&#39;s next login.</p><p>When the price file is missing, empty or carries no usable price, purchases are refused rather than granted for free.</p><h2 id="limits-—-capacity-ceilings" tabindex="-1"><code>limits</code> — Capacity Ceilings <a class="header-anchor" href="#limits-—-capacity-ceilings" aria-label="Permalink to “limits — Capacity Ceilings”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>max_pending_claim</code></td><td><code>100</code></td><td>How many unclaimed outputs one player may accumulate. New submissions are refused at the ceiling.</td></tr><tr><td><code>warn_material_types</code></td><td><code>50</code></td><td>Above this many material kinds in one recipe, only a warning is logged; loading is not blocked.</td></tr><tr><td><code>batch_multiplier_max</code></td><td><code>0</code></td><td>Maximum multiplier per submission. <code>0</code> means no extra limit, still bounded by material amounts.</td></tr></tbody></table><p>Material kind count is not limited by GUI slot count; <code>warn_material_types</code> is only a typo guard.</p><h2 id="storage-—-warehouse-channel" tabindex="-1"><code>storage</code> — Warehouse Channel <a class="header-anchor" href="#storage-—-warehouse-channel" aria-label="Permalink to “storage — Warehouse Channel”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Master switch. Once off, EmakiStation never calls EmakiStorage at all.</td></tr><tr><td><code>batch_max_ops</code></td><td><code>200</code></td><td>Maximum operations per batch, matching EmakiStorage&#39;s <code>behavior.batch_max_ops</code>.</td></tr></tbody></table><p>Even with <code>enabled</code> true, the warehouse channel additionally requires EmakiStorage to provide the <code>emakistorage:atomic_batch</code> capability. Without that capability there is <strong>no</strong> fallback to withdrawing item by item: that would make materials flash through the player&#39;s inventory once, creating an exploitable window instead.</p><p>When materials come from both the inventory and the warehouse, the plugin prefers the <code>emakistorage:reservation</code> capability: place a reservation in the warehouse (without actually withdrawing), spend from the inventory, then commit the reservation. A mid-way failure only needs the reservation released, and releasing cannot fail on warehouse capacity. On older EmakiStorage versions lacking that capability, it degrades to &quot;withdraw from the warehouse first, deposit back on failure&quot;, where the deposit itself may be refused for lack of capacity — hence inferior to the reservation path.</p><h2 id="persistence" tabindex="-1"><code>persistence</code> <a class="header-anchor" href="#persistence" aria-label="Permalink to “persistence”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>autosave_interval_seconds</code></td><td><code>60</code></td><td>Autosave interval in seconds.</td></tr><tr><td><code>save_on_submit</code></td><td><code>true</code></td><td>Whether to flush immediately after a successful submission instead of waiting for the next autosave.</td></tr></tbody></table><p>Entries in the queue file correspond to materials that have <strong>already been deducted</strong>, so this interval is shorter than the warehouse&#39;s autosave.</p><p>The queue file and the warehouse file are two independent files, so a hard crash can still leave them inconsistent (materials deducted but the entry unsaved, or the entry saved but the deduction unflushed). Every entry records its full consumption list to make manual reconciliation possible. Eliminating this window entirely would require a cross-plugin two-phase commit, which costs too much.</p><h2 id="gui" tabindex="-1"><code>gui</code> <a class="header-anchor" href="#gui" aria-label="Permalink to “gui”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>click_throttle_ms</code></td><td><code>200</code></td><td>Minimum interval between two clicks in one session, in milliseconds.</td></tr><tr><td><code>refresh_interval_ticks</code></td><td><code>20</code></td><td>How often an open window repaints its progress display, in ticks.</td></tr></tbody></table>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};